type Estado = { status: 'rascunho' | 'enviado' | 'aprovado' | 'cancelado'; historico: string[] };
type Acao = { tipo: 'enviar' } | { tipo: 'aprovar' } | { tipo: 'cancelar'; motivo: string };

function reducer(e: Estado, a: Acao): Estado {
  const vai = (status: Estado['status'], nota: string): Estado =>
    ({ status, historico: [...e.historico, nota] });
  switch (a.tipo) {
    case 'enviar': return e.status === 'rascunho' ? vai('enviado', 'enviado') : e;
    case 'aprovar': return e.status === 'enviado' ? vai('aprovado', 'aprovado') : e;
    case 'cancelar': return e.status === 'aprovado' ? e : vai('cancelado', `cancelado: ${a.motivo}`);
  }
}

const inicial: Estado = { status: 'rascunho', historico: [] };
const acoes: Acao[] = [
  { tipo: 'aprovar' }, { tipo: 'enviar' }, { tipo: 'aprovar' }, { tipo: 'cancelar', motivo: 'duplicado' },
];
const final = acoes.reduce(reducer, inicial);
console.log(final.status);
console.log(final.historico.join(' > '));
console.log(reducer(final, { tipo: 'enviar' }) === final);
console.log(inicial.historico.length);

type Estado = { itens: string[] };

const impuro = (e: Estado, item: string): Estado => {
  e.itens.push(item);
