    if (anteriores !== null && igualRaso(anteriores, props)) continue; // memo pula
    anteriores = props;
    renders++;
  }
  return renders;
}

const aoConcluirEstavel = () => {};          // como useCallback
console.log('função nova a cada render:', conta(() => ({ titulo: 'Tarefa', aoConcluir: () => {} })));
console.log('função estável:', conta(() => ({ titulo: 'Tarefa', aoConcluir: aoConcluirEstavel })));
