function janela(total: number, alturaLinha: number, alturaJanela: number, rolagem: number, folga = 2) {
  const primeira = Math.max(0, Math.floor(rolagem / alturaLinha) - folga);
  const ultima = Math.min(total - 1, Math.ceil((rolagem + alturaJanela) / alturaLinha) + folga);
  return `linhas ${primeira} a ${ultima}: ${ultima - primeira + 1} de ${total} no DOM`;
}

