const espera = (ms: number) => new Promise((r) => setTimeout(r, ms));

let servidor = ['Comprar filtro'];
let otimista: string[] | null = null;
const tela = () => (otimista ?? servidor).join(', ');

async function adicionar(titulo: string, falha: boolean) {
  otimista = [...servidor, `${titulo} (enviando)`];
  console.log('no clique:', tela());
  await espera(20);
  if (!falha) servidor = [...servidor, titulo];
  otimista = null;                            // a Action terminou
  console.log(falha ? 'falhou:' : 'gravou:', tela());
}

await adicionar('Ligar para Ana', false);
await adicionar('Pagar boleto', true);

type Estado = { erro: string | null; gravadas: number };

async function acao(anterior: Estado, titulo: string): Promise<Estado> {
  if (titulo.trim() === '') return { ...anterior, erro: 'Informe o título' };
  return { erro: null, gravadas: anterior.gravadas + 1 };
}

let estado: Estado = { erro: null, gravadas: 0 };
let pendente = false;

async function enviar(titulo: string) {
  pendente = true;
  console.log('pendente:', pendente);
  estado = await acao(estado, titulo);
  pendente = false;
  console.log(JSON.stringify(estado), 'pendente:', pendente);
}

await enviar('   ');
await enviar('Revisar PR');

declare function useActionState<S, P>(
  acao: (anterior: S, enviado: P) => S | Promise<S>,
  inicial: S,
): [estado: S, despachar: (enviado: P) => void, pendente: boolean];

type Estado = { erro: string | null };

async function gravar(anterior: Estado, dados: FormData): Promise<Estado> {
  const titulo = dados.get('titulo');
